<?php
require_once __DIR__.'/bootstrap.php';require_login();$rows=db()->query("SELECT d.*,(SELECT COUNT(*) FROM activations a WHERE a.device_id=d.device_id AND a.is_active=1) active_lists FROM devices d ORDER BY COALESCE(d.last_seen,d.created_at) DESC")->fetchAll();$pageTitle='Dispositivos Reconhecidos';include __DIR__.'/partials/header.php';
?>
<section class="card"><div class="section-title"><h2>Dispositivos</h2><span class="muted"><?=count($rows)?> reconhecido(s)</span></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Nome / Modelo</th><th>Versão</th><th>IP</th><th>Última conexão</th><th>Listas ativas</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">Nenhum dispositivo conectou ao painel ainda.</td></tr><?php endif?><?php foreach($rows as $r):$online=$r['last_seen'] && strtotime($r['last_seen'])>time()-600;?><tr><td><span class="code"><?=h($r['device_id'])?></span></td><td><b><?=h($r['device_name']?:'Android TV')?></b><div class="muted"><?=h($r['model'])?></div></td><td><?=h($r['app_version'])?></td><td><?=h($r['last_ip'])?></td><td><span class="badge <?=$online?'':'off'?>"><?=$online?'Online':h($r['last_seen']?:'Nunca')?></span></td><td><?=(int)$r['active_lists']?></td></tr><?php endforeach?></tbody></table></div></section>
<?php include __DIR__.'/partials/footer.php'; ?>
